/**
 * @param {Function[]} functions
 * @return {Function}
 */
var compose = function(functions) {
    return function(x) {
        return functions.reduceRight((acc, fn) => fn(acc), x);
    };
};

type F = (x: number) => number;

function compose(functions: F[]): F {
    return function(x: number): number {
        return functions.reduceRight((acc, fn) => fn(acc), x);
    };
}
